package core

import (
	"regexp"
	"strings"
)

var slugRegex = regexp.MustCompile(`[^a-z0-9]+`)

// Slugify converts a string into a slug containing only lowercase letters, digits, and hyphens.
func Slugify(s string) string {
	s = strings.ToLower(s)
	s = slugRegex.ReplaceAllString(s, "-")
	s = strings.Trim(s, "-")
	return s
}

package main

import (
	"log"
	"strings"

	"myproject/core"
	"github.com/pocketbase/pocketbase"
	pbCore "github.com/pocketbase/pocketbase/core"
)

func main() {
	app := pocketbase.New()

	// Register OnRecordCreateRequest hook for the "posts" collection
	app.OnRecordCreateRequest("posts").BindFunc(func(e *pbCore.RecordRequestEvent) error {
		title := e.Record.GetString("title")
		if strings.TrimSpace(title) == "" {
			return e.BadRequestError("Title cannot be empty", nil)
		}

		e.Record.Set("slug", core.Slugify(title))

		return e.Next()
	})

	if err := app.Start(); err != nil {
		log.Fatal(err)
	}
}
